:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 460px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 16px;
  gap: 12px;
}

h1 {
  font-size: 24px;
  margin: 0;
  letter-spacing: 1px;
}

.score {
  margin: 0;
  font-size: 18px;
  color: var(--muted);
}

.score span { color: var(--accent); font-weight: 700; }

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--grid);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(22, 33, 62, 0.92);
  padding: 20px;
  text-align: center;
}

.overlay-content h2 {
  margin: 0 0 12px;
  font-size: 22px;
  color: var(--accent);
}

.overlay-content p {
  margin: 0 0 20px;
  line-height: 1.6;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  margin-top: 16px;
}

.btn {
  flex: 1;
  padding: 12px 16px;
  font-size: 16px;
  font-family: inherit;
  font-weight: 600;
  color: var(--text);
  background: var(--grid);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.btn:hover { background: #1a4a7a; }

.btn:focus-visible {
  outline: none;
  border-color: var(--accent);
}

.btn:active { transform: scale(0.97); }

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover { background: #c73550; }

@media (max-width: 400px) {
  .game-card { padding: 16px; }
  h1 { font-size: 20px; }
  .score { font-size: 16px; }
  .btn { padding: 10px 12px; font-size: 15px; }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const COLS = 20;
  const ROWS = 20;
  const CELL = canvas.width / COLS;
  const TICK_MS = 130;

  const COLORS = {
    grid: '#0f3460',
    snake: '#4ecca3',
    head: '#3bb38a',
    food: '#e94560'
  };

  let state = 'paused'; // 'paused' | 'playing' | 'gameover'
  let snake, dir, nextDir, food, score, lastTick, rafId;

  function reset() {
    snake = [{ x: 9, y: 10 }, { x: 8, y: 10 }, { x: 7, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    lastTick = 0;
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * COLS), y: Math.floor(Math.random() * ROWS) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = COLORS.grid;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // food
    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    // snake
    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    // wall collision
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) {
      return gameOver();
    }
    // self collision (ignore tail that will move away)
    if (snake.some((s, i) => i < snake.length - 1 && s.x === head.x && s.y === head.y)) {
      return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }
  }

  function loop(ts) {
    if (state !== 'playing') return;
    if (ts - lastTick >= TICK_MS) {
      lastTick = ts;
      step();
      if (state !== 'playing') return;
    }
    draw();
    rafId = requestAnimationFrame(loop);
  }

  function start() {
    reset();
    state = 'playing';
    overlay.hidden = true;
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-pressed', 'false');
    lastTick = 0;
    cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(loop);
  }

  function pause() {
    if (state !== 'playing') return;
    state = 'paused';
    cancelAnimationFrame(rafId);
    pauseBtn.textContent = 'Resume';
    pauseBtn.setAttribute('aria-pressed', 'true');
  }

  function resume() {
    if (state !== 'paused') return;
    state = 'playing';
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-pressed', 'false');
    lastTick = 0;
    rafId = requestAnimationFrame(loop);
  }

  function togglePause() {
    if (state === 'playing') pause();
    else if (state === 'paused') resume();
  }

  function gameOver() {
    state = 'gameover';
    cancelAnimationFrame(rafId);
    overlayTitle.textContent = 'Game Over';
    overlayText.innerHTML = 'Final score: <strong>' + score + '</strong>';
    overlayBtn.textContent = 'Play Again';
    overlay.hidden = false;
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-pressed', 'false');
    draw();
  }

  function restart() {
    cancelAnimationFrame(rafId);
    state = 'paused';
    reset();
    draw();
    overlayTitle.textContent = 'How to Play';
    overlayText.innerHTML = 'Use the <strong>arrow keys</strong> to move the snake.<br>Eat the food to grow and score points.<br>Don\'t hit the walls or yourself!';
    overlayBtn.textContent = 'Start Game';
    overlay.hidden = false;
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-pressed', 'false');
  }

  function setDirection(nx, ny) {
    if (state !== 'playing') return;
    // prevent 180-degree reversal relative to current committed direction
    if (nx === -dir.x && ny === -dir.y) return;
    nextDir = { x: nx, y: ny };
  }

  // Keyboard controls
  document.addEventListener('keydown', function (e) {
    switch (e.key) {
      case 'ArrowUp':    e.preventDefault(); setDirection(0, -1); break;
      case 'ArrowDown':  e.preventDefault(); setDirection(0, 1);  break;
      case 'ArrowLeft':  e.preventDefault(); setDirection(-1, 0); break;
      case 'ArrowRight': e.preventDefault(); setDirection(1, 0);  break;
      case 'p': case 'P': e.preventDefault(); togglePause(); break;
      case 'r': case 'R': e.preventDefault(); restart(); break;
      case ' ': e.preventDefault();
        if (state === 'gameover') start();
        else togglePause();
        break;
    }
  });

  overlayBtn.addEventListener('click', function () {
    if (state === 'gameover') start();
    else start();
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  // Initial state: paused with how-to-play overlay
  reset();
  draw();
})();
